@Test
public void test() throws InterruptedException {
    final ThreadPoolExecutor executor = new ThreadPoolExecutor(MAX_THREADS, MAX_THREADS, Long.MAX_VALUE, TimeUnit.NANOSECONDS, new LinkedBlockingQueue<>());
    final URL url = Digester163TestCase.class.getResource("test.xml");
    final LinkedBlockingQueue<Exception> exceptions = new LinkedBlockingQueue<>();
    for (int i = 0; i < MAX_THREADS * 2; i++) {
        executor.submit(() -> {
            try {
                final Digester dig = loader.newDigester();
                // lets parse - result does not matter here
                dig.parse(url);
            } catch (final Exception e) {
                exceptions.add(e);
            }
        });
    }
    while (!executor.awaitTermination(10, TimeUnit.MILLISECONDS)) {
        if (executor.getQueue().isEmpty()) {
            executor.shutdown();
        }
        if (executor.isTerminated()) {
            break;
        }
    }
    Exception e = exceptions.peek();
    if (e != null) {
        while (true) {
            e = exceptions.poll();
            if (e == null) {
                break;
            }
            e.printStackTrace();
        }
        fail("Caught " + exceptions.size() + " exceptions.");
    }
}

