    // min/max rules should not be in effect
    // setproperties should not be in effect
    child = children.get(0);
    assertNotNull(child);
    assertInstanceOf(Slider.class, child);
    final Slider slider1 = (Slider) child;
    assertEquals("nolabel", slider1.getLabel());
